from fastapi import FastAPI
from fastapi.testclient import TestClient
from pydantic import BaseModel, Field

app = FastAPI()


class Q(BaseModel):
    n: int = Field(..., ge=1, le=3)


@app.post("/q")
def q(item: Q):
    return {"n": item.n * 2}


@app.get("/page")
def page(size: int = 2):
    return list(range(size))


client = TestClient(app)
print(client.post("/q", json={"n": 3}).json())
print(client.post("/q", json={"n": 4}).status_code)
print(client.post("/q", json={}).status_code)
print(client.get("/page").json())
print(client.get("/page", params={"size": 3}).json())
print(client.get("/page", params={"size": "x"}).status_code)
